import {createTakeAudition,takeSelection} from './take-audition.js';
export function mountTakeLanes({root,track,project,engine,assets,toast,updateTransport,esc,onChoose,busy=()=>false}){
 const section=document.createElement('section');section.className='take-lanes';section.innerHTML=`<div class="take-lane-title"><strong>PRISES · ÉCOUTER ET SÉLECTIONNER</strong><button id="takeAuditionStop" class="outline-btn">Stop</button></div><p>Écoute chaque prise sur la plage Début / Fin ci-dessous, avec les autres pistes. Glisse sur une alternative pour choisir un extrait à assembler.</p><label class="take-loop-control"><input type="checkbox" id="takeAuditionLoop"> Boucler la plage pendant l’écoute</label>${track.playlists.map(l=>`<div class="take-lane-row ${l.id===track.activePlaylist?'active':''}"><div><strong>${esc(l.name)}</strong><small>${l.id===track.activePlaylist?'ACTIVE':'ALTERNATIVE'}</small><button class="outline-btn" data-listen-take="${l.id}" aria-label="Écouter la prise ${esc(l.name)}">▶ Écouter</button><button class="outline-btn" data-choose-take="${l.id}" ${l.id===track.activePlaylist?'disabled':''}>Garder cette prise</button></div><div class="take-lane-wave" data-take-lane="${l.id}" aria-label="Sélectionner une plage de ${esc(l.name)}">${l.clips.map(c=>`<span class="take-audio-clip" style="left:${c.start/project.bars*100}%;width:${c.length/project.bars*100}%"><svg viewBox="0 0 120 36" preserveAspectRatio="none"><polyline points="${wave(assets.get(c.audioId)?.buffer,c,project.bpm)}"/></svg></span>`).join('')}<span class="take-range" hidden></span></div></div>`).join('')}<output id="takeAuditionStatus" role="status">Écoute temporaire ; les prises restent conservées.</output><output id="takeRangeStatus">Sélectionne une prise source ci-dessous ou une plage sur son onde.</output>`;
 root.prepend(section);const bounds=document.getElementById('compStart').closest('.workflow-grid');section.querySelector('.take-loop-control').before(bounds);const dialog=document.getElementById('modal'),status=section.querySelector('#takeAuditionStatus');
 const audition=createTakeAudition({engine,project,trackId:track.id,onChange:state=>{for(const button of section.querySelectorAll('[data-listen-take]'))button.setAttribute('aria-pressed',String(button.dataset.listenTake===state.playlistId));status.textContent=state.status==='idle'?'Écoute arrêtée. Le montage est conservé.':(state.status==='preparing'?'Préparation · ':'Écoute · ')+(track.playlists.find(l=>l.id===state.playlistId)?.name||'Prise');updateTransport();}});
 const stop=()=>audition.stop();let disposed=false;
 const dispose=()=>{if(disposed)return;disposed=true;audition.dispose();dialog.removeEventListener('close',dispose);observer.disconnect();};
 const observer=new MutationObserver(()=>{if(!section.isConnected)dispose();});observer.observe(dialog,{childList:true,subtree:true});dialog.addEventListener('close',dispose);
 section.querySelector('#takeAuditionStop').onclick=stop;
 for(const button of section.querySelectorAll('[data-listen-take]'))button.onclick=async()=>{if(busy())return toast('Termine la prise avant cette écoute.');try{const start=Number(document.getElementById('compStart').value)-1,end=Number(document.getElementById('compEnd').value)-1,playlist=track.playlists.find(l=>l.id===button.dataset.listenTake);for(const c of playlist.clips)if(c.audioId&&c.start<end&&c.start+c.length>start&&!assets.get(c.audioId)?.buffer)throw Error('Audio manquant dans cette prise.');await audition.listen(playlist.id,{start,end},{loop:section.querySelector('#takeAuditionLoop').checked});}catch(error){toast(error.message);}};
 for(const button of section.querySelectorAll('[data-choose-take]'))button.onclick=()=>{if(busy())return toast('Termine la prise avant ce choix.');stop();onChoose?.(button.dataset.chooseTake);};
 for(const id of ['compStart','compEnd','takeAuditionLoop'])document.getElementById(id).addEventListener('change',stop);
 for(const lane of section.querySelectorAll('[data-take-lane]')){let start=null;const position=e=>Math.max(0,Math.min(project.bars,(e.clientX-lane.getBoundingClientRect().left)/lane.clientWidth*project.bars)),update=end=>{const {start:from,end:to}=takeSelection(start,end,project.bars),range=lane.querySelector('.take-range');document.getElementById('compSource').value=lane.dataset.takeLane;document.getElementById('compStart').value=(from+1).toFixed(3);document.getElementById('compEnd').value=(to+1).toFixed(3);section.querySelectorAll('.take-range').forEach(el=>el.hidden=true);range.hidden=false;range.style.left=from/project.bars*100+'%';range.style.width=(to-from)/project.bars*100+'%';section.querySelector('#takeRangeStatus').textContent='Plage : mesure '+(from+1).toFixed(2)+' → '+(to+1).toFixed(2);};
  lane.onpointerdown=e=>{if(lane.dataset.takeLane===track.activePlaylist){toast('Sélectionne une prise alternative pour le comping.');return;}stop();start=position(e);lane.setPointerCapture(e.pointerId);update(start+.25);e.preventDefault();};lane.onpointermove=e=>{if(start!==null)update(position(e));};lane.onpointerup=()=>start=null;lane.onpointercancel=()=>start=null;
 }
 return dispose;
}
function wave(buffer,clip,bpm){if(!buffer)return '';const d=buffer.getChannelData(0),offset=Math.floor((clip.sourceOffset||0)*buffer.sampleRate),length=Math.min(d.length-offset,clip.length*240/bpm*buffer.sampleRate),points=[];for(let i=0;i<120;i++){let peak=0;for(let j=0;j<8;j++){const at=offset+Math.floor((i+j/8)/120*length);peak=Math.max(peak,Math.abs(d[at]||0));}points.push(`${i},${18-peak*17}`,`${i},${18+peak*17}`);}return points.join(' ');}
